let product='claude';
const answers={claude:{},codex:{},chatgpt:{}};
const $=id=>document.getElementById(id);
const fmt=n=>Math.round(n).toLocaleString('en-US');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cite=keys=>keys.map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener">${SOURCES[k][0]}</a>`).join(' · ');
function renderQuestions(){
 $('questions').innerHTML=questions.map(q=>`<article class="question"><h3>${q.title}</h3><p>${q.desc}</p><fieldset><legend>${q.title}</legend>${[['bad',q.bad],['good',q.good],['unknown','Unknown']].map(([v,label])=>`<label class="choice"><input type="radio" name="${q.id}" value="${v}" ${(answers[product][q.id]||'unknown')===v?'checked':''}><span>${label}</span></label>`).join('')}</fieldset></article>`).join('');
 $('questions').querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{answers[product][input.name]=input.value;renderResults();}));
 renderResults();
}
function orderedFindings(){return questions.filter(q=>answers[product][q.id]==='bad').sort((a,b)=>(a.severity==='red'?0:1)-(b.severity==='red'?0:1));}
function renderResults(){
 const known=questions.filter(q=>['bad','good'].includes(answers[product][q.id])).length;
 const good=questions.filter(q=>answers[product][q.id]==='good').length;
 const findings=orderedFindings();
 $('progress').textContent=`${known} of ${questions.length} checked · ${questions.length-known} unknown`;
 $('progress-fill').style.width=`${known/questions.length*100}%`;
 $('findings').innerHTML=findings.length?findings.map(q=>`<article class="finding"><span class="badge ${q.severity}">${q.severity.toUpperCase()} · ${q.severity==='red'?'ACT FIRST':'INVESTIGATE'}</span><h3>${q.title}</h3><p>${q.fix[product]}</p><details><summary>Why this is flagged</summary><p>You reported: “${q.bad}”. This identifies a plausible source of waste, not a measured cost.</p><p>${cite([q.source[product]])}</p></details></article>`).join(''):`<div class="finding"><span class="badge ${known===questions.length?'green':'unknown'}">${known===questions.length?'GREEN · REPORTED HEALTHY':'UNKNOWN · NEEDS INPUT'}</span><h3>${known===questions.length?'No issues reported':'Start with what you can verify'}</h3><p>${known===questions.length?'Your answers describe healthy practices. Validate with actual usage before claiming savings.':'Answer the checklist to see tailored actions. Unverified items are not scored green.'}</p></div>`;
 if(good&&findings.length)$('findings').insertAdjacentHTML('beforeend',`<p class="fine">${good} practices reported healthy. Keep them in place.</p>`);
}
function renderGuide(){
 $('guide-product').textContent=names[product];
 $('mechanisms').innerHTML=mechanisms.map(m=>`<article class="mechanism"><div><h3>${m.title}</h3><p class="meta">${m.label}</p></div><div><p>${m.text}</p><p><strong>${names[product]}:</strong> ${m.specific[product]}</p><p class="fix"><strong>Try this:</strong> ${m.fix}</p><p class="citation">${cite(m.sources)}</p></div></article>`).join('');
}
function renderEvidence(){
 $('claims').innerHTML=claims.map(([status,t,title,text,keys])=>`<article class="claim"><div><span class="badge ${status==='Supported'?'green':status==='Corrected'?'red':'amber'}">${status}</span></div><div><h3>${title}</h3><p>${text}</p><p class="citation">${cite(keys)}</p></div></article>`).join('');
 $('comparison').innerHTML=comparisons.map(([concept,a,b,c,keys])=>`<tr><th scope="row">${concept}<br><span class="citation">${cite(keys)}</span></th><td>${a}</td><td>${b}</td><td>${c}</td></tr>`).join('');
 $('sources').innerHTML=Object.values(SOURCES).map(([name,url,note])=>`<li><a href="${url}" target="_blank" rel="noopener">${name}</a><small>${note}</small></li>`).join('');
}
function calculateSession(b,g,n,noise){const removable=Math.min(b,noise);return {total:n*b+g*n*(n-1)/2,saved:n*removable,last:b+g*(n-1),removable};}
function calculateSchedule(hours,interval,tokens){const runs=hours===0?0:Math.ceil(hours*60/interval);return {runs,total:runs*tokens};}
function updateSimulation(){
 const b=Number($('base').value),g=Number($('growth').value),n=Number($('turns').value);
 $('noise').max=String(b);if(Number($('noise').value)>b)$('noise').value=String(b);
 const noise=Number($('noise').value),r=calculateSession(b,g,n,noise);
 [['base',b],['growth',g],['turns',n],['noise',noise]].forEach(([id,v])=>$(id+'-out').textContent=fmt(v));
 const max=Math.max(1,r.last);
 $('chart').innerHTML=Array.from({length:n},(_,i)=>{const original=b+g*i,lean=original-r.removable;return `<div class="chart-pair" title="Request ${i+1}: ${fmt(original)} original; ${fmt(lean)} after removal"><i class="original" style="height:${original/max*100}%"></i><i class="lean" style="height:${lean/max*100}%"></i></div>`;}).join('');
 $('chart').setAttribute('aria-label',`${n} requests. First input ${fmt(b)}, last input ${fmt(r.last)} tokens. Removing ${fmt(r.removable)} tokens lowers every request by that amount.`);
 $('total').textContent=fmt(r.total)+' tokens';$('saved').textContent=fmt(r.saved)+' tokens';
 $('sim-summary').textContent=`Removing ${fmt(r.removable)} starting tokens avoids ${fmt(r.saved)} tokens of repeated input exposure (${r.total?(r.saved/r.total*100).toFixed(1):'0.0'}%). The final original request holds ${fmt(r.last)} input tokens. Cache discounts and window management change the real cost.`;
}
function updateSchedule(){
 const controls=['hours','interval','run-tokens'].map($);
 if(controls.some(e=>e.value===''||!e.validity.valid)){ $('schedule-result').textContent='Enter values within the displayed limits; interval must be at least one minute.';return;}
 const r=calculateSchedule(...controls.map(e=>Number(e.value)));
 $('schedule-result').textContent=`${fmt(r.runs)} scheduled runs carry ${fmt(r.total)} input tokens in this scenario. Output and worker requests would add more usage.`;
}
function makePrompt(){
 const productPart={claude:'For Claude Code: record installed version and authentication/provider. Ask me for /context and /usage if you cannot invoke them. Inspect scoped CLAUDE.md files and imports, MCP configuration and actual ToolSearch/deferral status, applicable hooks, worker model settings, and schedules. Record only whether gateway variables are set; redact values. A non-first-party base URL can trigger upfront tool loading, but explicit overrides and provider capabilities matter. Verify the effective state. Separate main-conversation and worker TTLs; do not assume one hour for all requests.',codex:'For Codex: record surface (app, CLI, IDE, cloud), version, model, effort and authentication. Ask me for CLI /status or usage-settings output when needed. Inspect applicable AGENTS.md hierarchy, skills/plugin instructions, MCP server enablement and tool allow/deny lists, delegation, and scheduled work. Do not use Claude-specific commands, environment variables or TTL assumptions. OpenAI API cache pricing is not evidence of Codex subscription accounting.',chatgpt:'For ChatGPT: record mode, plan and available tools. Review only information I provide or you can legitimately access: conversation scope, attachments, custom/project instructions, memory settings, connected apps and scheduled tasks. Do not claim access to local files, hidden system prompts, per-turn token counts, cache TTL, or billing logs. Ask me for missing settings or usage-limit messages. Distinguish ordinary Chat from Work/agentic runs and API usage.'}[product];
 return `Audit my ${names[product]} workflow for avoidable token/context waste. Report only; change no file, setting, integration or task. Keep the audit itself small and bounded. Start with current context and a narrow configuration inventory; do not scan all history by default.

${productPart}

Check seven areas:
1. Context and instructions: distinguish current window occupancy from cumulative usage. List relevant instruction files/settings, duplicates and scope. Count tokens with a matching tokenizer if available; label byte/character estimates as estimates. Do not use arbitrary file-size thresholds as proof of waste.
2. Tools: separate tool listings, loaded schemas, arguments and result content. Identify unused capabilities, broad queries, repeated reads and oversized output. Missing hooks alone is not evidence of waste. Preserve failures and exit status in any suggested output filter.
3. Model and effort: report effective values and where configured. Identify unnecessary retries and task/model mismatch. Assess any transition overhead against remaining work; never assume every switch is a net loss.
4. Delegation: count parent and worker work, copied context, duplicate reads and returned summaries. Separate parent-context savings from total usage and quality.
5. Background work: list only relevant active loops, schedules and workers with cadence, runtime requirements, context mode, last useful outcome and stop condition. Idle apps and background shell jobs are not automatically model calls. Do not recommend extra runs to keep cache warm.
6. Cache and usage: where exposed, use a bounded sample of unique request IDs, deduplicating streaming or repeated log events. Separate uncached input, cache write, cache read, output and reasoning according to the provider schema. Do not double-count nested totals. Report cache-read share of total input, not dollar share. Compare TTL with actual observed requests, prefix matches and other activity; interval alone does not prove a miss.
7. Evidence and cost: include exact observations and measurement period. Estimate money only with verified model/provider rates and a matching billing mode. Never translate API dollars into subscription quota. Say UNKNOWN for hidden data. Do not print credentials, secret environment values or raw sensitive log content.

Output a compact table:
FINDING | RED/AMBER/GREEN/UNKNOWN | MEASURED EVIDENCE | IMPACT (MEASURED/ESTIMATED/UNKNOWN) | NEXT ACTION
RED means a verified, actionable high-priority issue; AMBER means a plausible issue needing investigation; GREEN means verified acceptable behavior; UNKNOWN means insufficient data. Rank by measured impact when comparable; otherwise explain the qualitative priority. Cite current official documentation for product-specific mechanisms and state any version caveats.

End with one highest-value next action and a small before/after validation plan. Do not modify anything.`;
}
function setProduct(next){product=next;$('environment-note').textContent=notes[product];renderQuestions();renderGuide();$('audit-prompt').value=makePrompt();$('copy-status').textContent='';}
const views={audit:['Find what’s filling your context.','Check your workflow. See the likely waste. Leave with a specific next step.'],simulate:['See how context repeats.','Change the inputs to explore accumulation and recurring work.'],guide:['Make each request more useful.','Understand the mechanism before changing your workflow.'],evidence:['Separate facts from rules of thumb.','Check which claims hold, which need qualification, and what transfers.'],prompt:['Turn suspicions into evidence.','A bounded, read-only audit adapted to your environment.']};
function navigate(){let name=location.hash.slice(1);if(!views[name])name='audit';document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('[data-view]').forEach(e=>{e.classList.toggle('active',e.dataset.view===name);if(e.dataset.view===name)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});$('page-title').textContent=views[name][0];$('page-description').textContent=views[name][1];}
function downloadReport(){const lines=[`# Context Lab audit: ${names[product]}`,`Research snapshot: 7 October 2026`,`Answers exported: ${new Date().toISOString()}`,'','Self-reported practices, not account telemetry. Severity is qualitative; costs are unknown.',''];const order=[...orderedFindings(),...questions.filter(q=>answers[product][q.id]!=='bad')];order.forEach(q=>{const a=answers[product][q.id]||'unknown';lines.push(`## ${a==='bad'?q.severity.toUpperCase():a==='good'?'GREEN (self-reported)':'UNKNOWN'}: ${q.title}`,`Answer: ${a==='bad'?q.bad:a==='good'?q.good:'Unknown'}`,a==='bad'?`Next action: ${q.fix[product]}`:'Validate using product diagnostics.',`Source: ${SOURCES[q.source[product]][1]}`,'');});const blob=new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`context-lab-${product}-audit.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('product').addEventListener('change',e=>setProduct(e.target.value));
$('reset').addEventListener('click',()=>{answers[product]={};renderQuestions();});
$('export-report').addEventListener('click',downloadReport);
['base','growth','turns','noise'].forEach(id=>$(id).addEventListener('input',updateSimulation));
['hours','interval','run-tokens'].forEach(id=>$(id).addEventListener('input',updateSchedule));
$('copy-prompt').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('audit-prompt').value);$('copy-status').textContent='Prompt copied.';}catch{ $('audit-prompt').focus();$('audit-prompt').select();$('copy-status').textContent='Clipboard access unavailable. The prompt is selected; copy it using your keyboard.';}});
document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{
 const name=link.getAttribute('href').slice(1);
 if(!views[name])return;
 event.preventDefault();history.pushState(null,'','#'+name);navigate();window.scrollTo(0,0);
 $('page-title').setAttribute('tabindex','-1');$('page-title').focus({preventScroll:true});
}));
window.addEventListener('hashchange',navigate);
window.addEventListener('popstate',navigate);
renderEvidence();setProduct('claude');updateSimulation();updateSchedule();navigate();
